 3	pub fn camelize(word: &str) -> String {
 4	    let mut bytes = Vec::with_capacity(word.len());
 5	    let mut uppercase_next = false;
 6	
 7	    for &byte in word.as_bytes() {
 8	        if byte == b'_' {
 9	            uppercase_next = true;
10	            continue;
11	        }
12	
13	        if uppercase_next {
14	            bytes.push(byte.to_ascii_uppercase());
15	            uppercase_next = false;
16	        } else {
17	            bytes.push(byte);
18	        }
19	    }
20	
21	    String::from_utf8(bytes).expect("ASCII byte edits preserve UTF-8")
22	}
