24	pub fn underscore(word: &str) -> String {
25	    let mut bytes = Vec::with_capacity(word.len() * 2);
26	
27	    for (index, &byte) in word.as_bytes().iter().enumerate() {
28	        if byte.is_ascii_uppercase() {
29	            if index != 0 {
30	                bytes.push(b'_');
31	            }
32	            bytes.push(byte.to_ascii_lowercase());
33	        } else {
34	            bytes.push(byte);
35	        }
36	    }
37	
